const setsOnDisk = `-- name: SetsOnDisk :many
SELECT id, project_id, deployment, taken_at, trigger, actor, actor_principal, actor_via, path, bytes, items_json, status, error, store, data_class, store_endpoint, store_bucket FROM backups WHERE store=$1 AND status IN ($2,$3) ORDER BY id
`

type SetsOnDiskParams struct {
	Disk         string
	OkState      string
	PartialState string
}

func (q *Queries) SetsOnDisk(ctx context.Context, arg SetsOnDiskParams) ([]Backup, error) {
	rows, err := q.db.QueryContext(ctx, setsOnDisk, arg.Disk, arg.OkState, arg.PartialState)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Backup
	for rows.Next() {
		var i Backup
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Deployment,
			&i.TakenAt,
			&i.Trigger,
			&i.Actor,
			&i.ActorPrincipal,
			&i.ActorVia,
			&i.Path,
			&i.Bytes,
			&i.ItemsJson,
			&i.Status,
			&i.Error,
			&i.Store,
			&i.DataClass,
			&i.StoreEndpoint,
			&i.StoreBucket,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

